<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <h1 id="page-title">Notification Preferences</h1>
      <p class="intro">Choose the channel that works best for important account updates.</p>

      <form id="notification-form" novalidate>
        <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>

        <fieldset class="form-field" aria-describedby="notification-help notification-error">
          <legend>
            How do you prefer to receive notifications?
            <span class="required-marker" aria-hidden="true">*</span>
          </legend>
          <p id="notification-help" class="field-help">Select one notification method.</p>

          <div class="options">
            <label class="option" for="notification-email">
              <input id="notification-email" type="radio" name="notificationPreference" value="Email" required>
              <span>Email</span>
            </label>

            <label class="option" for="notification-sms">
              <input id="notification-sms" type="radio" name="notificationPreference" value="SMS" required>
              <span>SMS</span>
            </label>

            <label class="option" for="notification-push">
              <input id="notification-push" type="radio" name="notificationPreference" value="Push Notifications" required>
              <span>Push Notifications</span>
            </label>
          </div>

          <p id="notification-error" class="error-message" aria-live="polite"></p>
        </fieldset>

        <button type="submit">Save preference</button>
        <p id="form-status" class="success-message" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#notification-form");
    const radios = Array.from(document.querySelectorAll('input[name="notificationPreference"]'));
    const errorMessage = document.querySelector("#notification-error");
    const statusMessage = document.querySelector("#form-status");

    function selectedPreference() {
      return radios.find((radio) => radio.checked);
    }

    function clearMessages() {
      errorMessage.textContent = "";
      statusMessage.textContent = "";
      radios.forEach((radio) => radio.removeAttribute("aria-invalid"));
    }

    radios.forEach((radio) => {
      radio.addEventListener("change", clearMessages);
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      clearMessages();

      const selected = selectedPreference();

      if (!selected) {
        errorMessage.textContent = "Error: Choose one notification method.";
        radios.forEach((radio) => radio.setAttribute("aria-invalid", "true"));
        radios[0].focus();
        return;
      }

      statusMessage.textContent = `Preference saved: ${selected.value}.`;
    });
  </script>
</body>
</html>
